    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_support_assignment PRIMARY KEY (tenant_identifier, person_support_assignment_identifier)
);
COMMENT ON TABLE advising.person_support_assignment IS 'Records an institutionally assigned person-to-person support relationship, identifying the person receiving support, the person providing support, the governed role being performed, whether the assignment is primary within the applicable support role or context, and the effective period. The assignment is not defined by a particular caseload, advising program, academic program, or source-system implementation.';
