-- PersonSupportReferral
-- A tenant-scoped referral of a person to one or more support destinations such as a resource,
-- service provider, person, or organization. The referral may originate from an early-alert
-- response, an identified person challenge, or another support workflow. At least one destination
-- reference must be populated. Referral lifecycle and outcome fields support closed-loop
-- student-support interoperability without making the referral dependent on any one vendor
-- workflow.
CREATE TABLE advising.person_support_referral (
    tenant_identifier                                UUID NOT NULL,
    person_support_referral_identifier               TEXT NOT NULL,
    person_identifier                                TEXT NOT NULL,
    referring_person_identifier                      TEXT,
    resource_identifier                              TEXT,
    referred_person_identifier                       TEXT,
    referred_organization_identifier                 TEXT,
    learner_early_alert_activity_identifier          TEXT,
    person_challenge_identifier                      TEXT,
    referral_date_time                               TIMESTAMP WITH TIME ZONE NOT NULL,
    referral_status_identifier                       TEXT,
    referral_reason                                  TEXT,
    outcome_description                              TEXT,
    closed_date_time                                 TIMESTAMP WITH TIME ZONE,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_support_referral PRIMARY KEY (tenant_identifier, person_support_referral_identifier)
);
COMMENT ON TABLE advising.person_support_referral IS 'A tenant-scoped referral of a person to one or more support destinations such as a resource, service provider, person, or organization. The referral may originate from an early-alert response, an identified person challenge, or another support workflow. At least one destination reference must be populated. Referral lifecycle and outcome fields support closed-loop student-support interoperability without making the referral dependent on any one vendor workflow.';
COMMENT ON COLUMN advising.person_support_referral.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
