COMMENT ON COLUMN advising.person_support_referral.deleted_date IS 'Date and time record was deleted.';

-- SpecialtyLookup
-- A lookup table containing descriptions of specialties of academic advisors or members of the
-- care team.
CREATE TABLE advising.specialty_lookup (
    tenant_identifier                                UUID NOT NULL,
    specialty_identifier                             TEXT NOT NULL,
    source_system_identifier                         TEXT,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    status                                           TEXT NOT NULL,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_specialty_lookup PRIMARY KEY (tenant_identifier, specialty_identifier)
);
COMMENT ON TABLE advising.specialty_lookup IS 'A lookup table containing descriptions of specialties of academic advisors or members of the care team.';
COMMENT ON COLUMN advising.specialty_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN advising.specialty_lookup.specialty_identifier IS 'Unique identifier for a specialty item';
COMMENT ON COLUMN advising.specialty_lookup.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN advising.specialty_lookup.name IS 'A name for the record';
COMMENT ON COLUMN advising.specialty_lookup.description IS 'A description for the record';
COMMENT ON COLUMN advising.specialty_lookup.status IS 'Status of the lookup item (active, inactive)';
COMMENT ON COLUMN advising.specialty_lookup.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN advising.specialty_lookup.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN advising.specialty_lookup.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN advising.specialty_lookup.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN advising.specialty_lookup.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN advising.specialty_lookup.created_date IS 'Date and time record was created';
COMMENT ON COLUMN advising.specialty_lookup.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN advising.specialty_lookup.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN advising.specialty_lookup.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN advising.specialty_lookup.deleted_date IS 'Date and time record was deleted';

-- SupportAssignmentRoleLookup
-- Tenant-governed vocabulary of institutional support roles used when one person is assigned to
-- support another person, such as academic advisor, success coach, career advisor, or peer
-- advisor. Roles describe the function performed in the relationship and remain distinct from
-- staff specialties.
CREATE TABLE advising.support_assignment_role_lookup (
    tenant_identifier                                UUID NOT NULL,
    support_assignment_role_identifier               TEXT NOT NULL,
    code                                             TEXT NOT NULL,
    title                                            TEXT NOT NULL,
    description                                      TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_support_assignment_role_lookup PRIMARY KEY (tenant_identifier, support_assignment_role_identifier)
);
COMMENT ON TABLE advising.support_assignment_role_lookup IS 'Tenant-governed vocabulary of institutional support roles used when one person is assigned to support another person, such as academic advisor, success coach, career advisor, or peer advisor. Roles describe the function performed in the relationship and remain distinct from staff specialties.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.support_assignment_role_identifier IS 'Tenant-scoped identifier for the governed support role.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.code IS 'Institution-defined code for the support role.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.title IS 'Human-readable name of the support role.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.description IS 'Description of the function performed by a support person in this role.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.source_system_identifier IS 'Identifier for the source system from which the canonical role definition was imported or reconciled.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.source_system_key_value IS 'Identifier of the support-role definition in the source system.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.created_by IS 'Person identifier that created the canonical role row.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.created_date IS 'Date and time the canonical role row was created.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.updated_by IS 'Person identifier that last updated the canonical role row.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.updated_date IS 'Date and time the canonical role row was last updated.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.deleted_by IS 'Person identifier that soft-deleted the canonical role row.';
COMMENT ON COLUMN advising.support_assignment_role_lookup.deleted_date IS 'Date and time the canonical role row was soft-deleted, if applicable.';
